import{_ as e,o,c as a,a2 as d}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Hotkeys","description":"","frontmatter":{},"headers":[],"relativePath":"user-guide/hotkeys.md","filePath":"user-guide/hotkeys.md","lastUpdated":1783494793000}'),r={name:"user-guide/hotkeys.md"};function s(i,t,l,n,h,c){return o(),a("div",null,[...t[0]||(t[0]=[d('<h1 id="hotkeys" tabindex="-1">Hotkeys <a class="header-anchor" href="#hotkeys" aria-label="Permalink to &quot;Hotkeys&quot;">​</a></h1><p>All global and in-app hotkeys below can be rebound from <strong>Settings → Hotkeys</strong>; defaults are shown here. See <a href="./settings/hotkeys-page.html">Settings → Hotkeys page</a> for the settings UI itself.</p><h2 id="global-hotkeys" tabindex="-1">Global hotkeys <a class="header-anchor" href="#global-hotkeys" aria-label="Permalink to &quot;Global hotkeys&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Action</th><th>Default</th><th>Notes</th></tr></thead><tbody><tr><td>Toggle quick window</td><td>Double-tap <code>Ctrl</code></td><td>Can also be set to a full combo (e.g. <code>Alt+Space</code>) instead of a double-tap.</td></tr><tr><td>Quick switch</td><td><code>Ctrl+G</code></td><td>Switches between the inline (embedded-in-Explorer) search bar and the main window.</td></tr><tr><td>Select next item</td><td><code>Ctrl+N</code></td><td>Also works as the literal Down arrow.</td></tr><tr><td>Select previous item</td><td><code>Ctrl+P</code></td><td>Also works as the literal Up arrow.</td></tr><tr><td>Jump to result 1–9</td><td><code>Ctrl</code> + digit</td><td>The modifier is configurable; the digit is always 1–9.</td></tr><tr><td>Open actions menu</td><td><code>Ctrl+O</code></td><td>Also works as the literal Right arrow on a selected result.</td></tr><tr><td>Complete from selection</td><td><code>Ctrl+Tab</code></td><td>In the quick window, fills the search box with the selected result&#39;s name/path.</td></tr><tr><td>QuickLook preview</td><td><code>Alt+P</code></td><td>Toggles the preview pane for the selected result.</td></tr><tr><td>Previous keyword history</td><td><code>Alt+Up</code></td><td>Cycles backward through your recently typed queries.</td></tr><tr><td>Next keyword history</td><td><code>Alt+Down</code></td><td>Cycles forward through your recently typed queries.</td></tr><tr><td>Delete keyword history entry</td><td><code>Shift+Delete</code></td><td></td></tr><tr><td>Next Startup Panel tab</td><td><code>Ctrl+Right</code></td><td>Wraps from the last tab back to the first. Only active while the <a href="./settings/startup-panel.html">Startup Panel</a> is showing — otherwise the key does its normal job (e.g. moving the caret while typing a query).</td></tr><tr><td>Previous Startup Panel tab</td><td><code>Ctrl+Left</code></td><td>Wraps from the first tab back to the last. Same active-only-while-showing rule as above.</td></tr></tbody></table><h2 id="quick-navigation-mouse" tabindex="-1">Quick navigation (mouse) <a class="header-anchor" href="#quick-navigation-mouse" aria-label="Permalink to &quot;Quick navigation (mouse)&quot;">​</a></h2><p>Enabled by default, toggled per-trigger in settings:</p><ul><li><strong>Double-click</strong> empty space in a supported window to trigger quick navigation.</li><li><strong>Middle-click</strong> empty space in a supported window to trigger quick navigation.</li></ul><h2 id="hardcoded-keys-not-configurable" tabindex="-1">Hardcoded keys (not configurable) <a class="header-anchor" href="#hardcoded-keys-not-configurable" aria-label="Permalink to &quot;Hardcoded keys (not configurable)&quot;">​</a></h2><p>These always behave the same way regardless of your hotkey settings:</p><table tabindex="0"><thead><tr><th>Key</th><th>Context</th><th>Behavior</th></tr></thead><tbody><tr><td><code>Escape</code></td><td>Anywhere</td><td>Clears the search box if it has text; otherwise closes the window (or exits the actions menu).</td></tr><tr><td><code>Enter</code></td><td>Result list</td><td>Opens the selected result.</td></tr><tr><td><code>Ctrl+Enter</code></td><td>Result list</td><td>Locates the result in Explorer instead of opening it.</td></tr><tr><td><code>Ctrl+Shift+Enter</code></td><td>Result list</td><td>Opens the result elevated (Run as administrator).</td></tr><tr><td><code>Left</code> / <code>Right</code> arrow</td><td>Actions menu</td><td>Go back a menu level / enter a submenu.</td></tr><tr><td><code>Backspace</code></td><td>Actions menu</td><td>Exits the actions menu when the search box is already empty.</td></tr></tbody></table><h2 id="plugin-action-hotkeys" tabindex="-1">Plugin action hotkeys <a class="header-anchor" href="#plugin-action-hotkeys" aria-label="Permalink to &quot;Plugin action hotkeys&quot;">​</a></h2><p>Plugins can register their own actions with a default hotkey (e.g. copy path, run as admin). These show up under <strong>Settings → Hotkeys → Plugin Actions</strong>, grouped by the plugin that registered them, and can be rebound the same way as built-in hotkeys.</p><h2 id="process-blacklist" tabindex="-1">Process blacklist <a class="header-anchor" href="#process-blacklist" aria-label="Permalink to &quot;Process blacklist&quot;">​</a></h2><p>If SwiftList&#39;s global hotkeys interfere with another application (a game capturing raw keyboard input, for example), add that process to the <strong>Process Blacklist</strong> — see <a href="./settings/hotkeys-page.html#process-blacklist">Settings → Hotkeys page</a>. While a blacklisted process is in the foreground, SwiftList&#39;s global hotkeys are let through untouched.</p>',14)])])}const p=e(r,[["render",s]]);export{g as __pageData,p as default};
